import org.junit.jupiter.api.Test;
import java.math.BigDecimal;
import java.util.Date;

import static org.junit.jupiter.api.Assertions.*;

public class TransferFundsResponseBusinessTest {

    @Test
    public void testGettersAndSetters() {
        TransferFundsResponseBusiness biz = new TransferFundsResponseBusiness();
        biz.setTransferId("TX123");
        biz.setTransferStatus("SUCCESS");
        biz.setCurrency("USD");
        biz.setAmount(new BigDecimal("100.00"));
        biz.setFraudCheckSkipped(true);

        assertEquals("TX123", biz.getTransferId());
        assertEquals("SUCCESS", biz.getTransferStatus());
