import com.fasterxml.jackson.databind.SerializationFeature;
import com.fasterxml.jackson.dataformat.xml.XmlMapper;
import com.fasterxml.jackson.dataformat.xml.ser.ToXmlGenerator;

import java.math.BigDecimal;
import java.text.SimpleDateFormat;
import java.util.Date;

public class TransferFundsResponseMapper {

    private final XmlMapper xmlMapper;

    public TransferFundsResponseMapper() {
        this.xmlMapper = new XmlMapper();
        this.xmlMapper.configure(ToXmlGenerator.Feature.WRITE_XML_DECLARATION, false);
        this.xmlMapper.disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS);
    }

    public String format(TransferFundsResponseBusiness business) throws Exception {
        if (business == null) {
            return "<TransferFundsResponse xmlns:xsi=\"http://www.w3.org/2001/XMLSchema-instance\" xsi:nil=\"true\"/>";
        }

        TransferFundsResponseXml wire = new TransferFundsResponseXml();
        wire.transferId = business.getTransferId();
        wire.transferStatus = business.getTransferStatus();

        if (business.getExecutionDate() != null) {
            SimpleDateFormat sdf = new SimpleDateFormat("yyyyMMdd");
            wire.executionDate = sdf.format(business.getExecutionDate());
        }

        if (business.getExecutionTime() != null) {
            SimpleDateFormat timeSdf = new SimpleDateFormat("HH:mm:ss");
            wire.executionTime = timeSdf.format(business.getExecutionTime());
        } else {
            wire.executionTime = "00:00:00";
        }

        if (business.getAmount() != null) {
            wire.amount = business.getAmount().setScale(2).toPlainString();
        }

        wire.currency = business.getCurrency();

        String srcAcc = business.getSourceAccount() != null ? business.getSourceAccount() : "";
        if (srcAcc.length() < 3) {
            srcAcc = " ".repeat(3 - srcAcc.length()) + srcAcc;
        }
        wire.sourceAccount = srcAcc;

        String tgtAcc = business.getTargetAccount() != null ? business.getTargetAccount() : "";
        if (tgtAcc.length() < 10) {
            tgtAcc = "0".repeat(10 - tgtAcc.length()) + tgtAcc;
        }
        wire.targetAccount = tgtAcc;

        if (business.getNewSourceBalance() != null) {
            wire.newSourceBalance = business.getNewSourceBalance().setScale(2).toPlainString();
        }

        if (business.getFraudCheckSkipped() != null) {
            wire.fraudCheckSkipped = business.getFraudCheckSkipped() ? "true" : "false";
        }

        if (isNil(business)) {
            wire.xsiNil = "true";
        }

        return xmlMapper.writeValueAsString(wire);
    }

    public TransferFundsResponseBusiness unformat(String xml) throws Exception {
        if (xml == null || xml.isBlank() || xml.contains("xsi:nil=\"true\"")) {
            return null;
        }
        TransferFundsResponseXml wire = xmlMapper.readValue(xml, TransferFundsResponseXml.class);
        TransferFundsResponseBusiness biz = new TransferFundsResponseBusiness();

        biz.setTransferId(wire.transferId);
        biz.setTransferStatus(wire.transferStatus);

        if (wire.executionDate != null && !wire.executionDate.isBlank()) {
            SimpleDateFormat sdf = new SimpleDateFormat("yyyyMMdd");
            biz.setExecutionDate(sdf.parse(wire.executionDate));
        }

        if (wire.executionTime != null && !wire.executionTime.isBlank()) {
            SimpleDateFormat timeSdf = new SimpleDateFormat("HH:mm:ss");
            try {
                biz.setExecutionTime(timeSdf.parse(wire.executionTime));
            } catch (Exception e) {
                biz.setExecutionTime(new Date(0L));
            }
        }

        if (wire.amount != null && !wire.amount.isBlank()) {
            biz.setAmount(new BigDecimal(wire.amount.replace(",", "")));
        }

        biz.setCurrency(wire.currency);

        String src = wire.sourceAccount;
        if (src != null) {
            src = src.replaceFirst("^ +", "");
            biz.setSourceAccount(src);
        }

        String tgt = wire.targetAccount;
        if (tgt != null) {
            tgt = tgt.replaceFirst("^0+", "");
            if (tgt.isEmpty()) tgt = "0";
            biz.setTargetAccount(tgt);
        }

        if (wire.newSourceBalance != null && !wire.newSourceBalance.isBlank()) {
            biz.setNewSourceBalance(new BigDecimal(wire.newSourceBalance.replace(",", "")));
        }

        if (wire.fraudCheckSkipped != null && !wire.fraudCheckSkipped.isBlank()) {
            biz.setFraudCheckSkipped(Boolean.parseBoolean(wire.fraudCheckSkipped) || "true".equalsIgnoreCase(wire.fraudCheckSkipped));
        }

        return biz;
    }

    private boolean isNil(TransferFundsResponseBusiness biz) {
        return biz.getTransferId() == null && biz.getTransferStatus() == null && biz.getAmount() == null && biz.getSourceAccount() == null;
    }
}

