package com.company.generated.units.ub5afca9c05e0;

import org.junit.jupiter.api.Test;
import java.math.BigDecimal;
import java.util.Date;

import static org.junit.jupiter.api.Assertions.*;

public class TransferFundsResponseMapperTest {

    @Test
    public void testFormatAndUnformat() throws Exception {
        TransferFundsResponseMapper mapper = new TransferFundsResponseMapper();

        TransferFundsResponseBusiness business = new TransferFundsResponseBusiness();
        business.setTransferId("T999");
        business.setTransferStatus("COMPLETED");
        business.setExecutionDate(new Date(1700000000000L));
        business.setAmount(new BigDecimal("250.50"));
        business.setCurrency("USD");
        business.setSourceAccount("123");
        business.setTargetAccount("456789");
        business.setNewSourceBalance(new BigDecimal("749.50"));
        business.setFraudCheckSkipped(false);

        String xml = mapper.format(business);
        assertNotNull(xml);
        assertTrue(xml.contains("<TransferId>T999</TransferId>"));
        assertTrue(xml.contains("<SourceAccount>  123</SourceAccount>"));
        assertTrue(xml.contains("<TargetAccount>0000456789</TargetAccount>"));

        TransferFundsResponseBusiness unformatted = mapper.unformat(xml);
        assertNotNull(unformatted);
        assertEquals("T999", unformatted.getTransferId());
        assertEquals("COMPLETED", unformatted.getTransferStatus());
        assertEquals("123", unformatted.getSourceAccount());
        assertEquals("456789", unformatted.getTargetAccount());
        assertEquals(new BigDecimal("250.50"), unformatted.getAmount());
        assertFalse(unformatted.getFraudCheckSkipped());
    }

    @Test
    public void testNilResponse() throws Exception {
        TransferFundsResponseMapper mapper = new TransferFundsResponseMapper();
        String nilXml = mapper.format(null);
        assertTrue(nilXml.contains("xsi:nil=\"true\""));

        TransferFundsResponseBusiness unformatted = mapper.unformat(nilXml);
        assertNull(unformatted);
    }
}

