    public Tag() {
    }

    public Tag(Map<String, String> attributes) {
        this.attributes.putAll(attributes);
    }

    public String getAttribute(String name) {
        return attributes.get(name);
    }

    public void setAttribute(String name, String value) {
        attributes.put(name, value);
    }
}

package com.ibm.il.dse.cc.decorator;

import com.ibm.dse.base.FormatDecoratorHolder;
import com.ibm.dse.base.Tag;

/**
 * Pads a string to a fixed length using a specified pad character.
 *
 * Attributes:
 *   padChar  - character to use for padding (default '0')
 *   length   - target length after padding
 *   padLeft  - "true" to pad on left (default), "false" to pad on right
 *
 * Format direction (addDecoration):    pad value to target length
 * Unformat direction (removeDecoration): strip the padding characters
 *
 * Decorator chain example with two decorators:
 *   <CCString dataName="AccountNumber"/>
 *   <RemoveLeadingZerosDecorator/>
 *   <CCPadding padChar="0" length="10"/>
 *
 *   format:   "12345" -> RemoveLeadingZeros.add (no-op) -> CCPadding.add -> "0000012345"
 *   unformat: "0000012345" -> CCPadding.remove -> "12345" -> RemoveLeadingZeros.remove -> "12345"
 */
public class CCPadding extends FormatDecoratorHolder {

    private char    padChar = '0';
    private int     length  = 0;
    private boolean padLeft = true;

    @Override
    public Object initializeFrom(Tag tag) {
        String pc = tag.getAttribute("padChar");
        if (pc != null && !pc.isBlank()) this.padChar = pc.charAt(0);
        String len = tag.getAttribute("length");
        if (len != null) this.length = Integer.parseInt(len.trim());
        String pl = tag.getAttribute("padLeft");
        if ("false".equalsIgnoreCase(pl)) this.padLeft = false;
        return this;
    }

    @Override
    public String addDecoration(String value) {
        if (value == null) value = "";
        if (value.length() >= length) return value;
        String pad = String.valueOf(padChar).repeat(length - value.length());
        return padLeft ? pad + value : value + pad;
    }

    @Override
    public String removeDecoration(String value) {
        if (value == null) return null;
        if (padLeft) {
            return value.replaceFirst("^[" + java.util.regex.Pattern.quote(String.valueOf(padChar)) + "]+", "");
        } else {
            return value.replaceFirst("[" + java.util.regex.Pattern.quote(String.valueOf(padChar)) + "]+$", "");
        }
    }
}

package com.ibm.il.dse.cc.decorator;

import com.ibm.dse.base.FormatDecoratorHolder;

/**
 * Sets xsi:nil="true" attribute when value is null or empty.
 * Implements Type 1 decorator contract (FormatDecoratorHolder).
 *
 * Format direction (addDecoration):   null/empty -> add xsi:nil="true" attribute
 * Unformat direction (removeDecoration): xsi:nil value -> return null
 */
public class NilDecorator extends FormatDecoratorHolder {

    /** Called during FORMAT. If value is null/empty, adds nil attribute. */
    @Override
    public String addDecoration(String value) {
        if (value == null || value.isBlank()) {
            // Signal to parent formatter to emit xsi:nil="true"
            return null;
        }
        return value;
    }

    /** Called during UNFORMAT (in reverse chain order). Null value -> empty string. */
    @Override
    public String removeDecoration(String value) {
        if (value == null) return "";
        return value;
    }
}

package com.ibm.il.dse.cc.format;

import com.ibm.dse.base.Context;
import com.ibm.dse.base.Tag;

/**
 * Boolean field formatter. Maps "true"/"false" XML values to/from context.
 *
 * Attributes:
 *   dataName - the XML element name and context field name
 *   trueValue  - XML string representing true  (default: "true")
 *   falseValue - XML string representing false (default: "false")
 */
public class CCBoolean extends AbstractFormatElement {

    private String dataName;
    private String trueValue  = "true";
    private String falseValue = "false";

    @Override
    public void initializeFrom(Tag tag) {
        this.dataName   = tag.getAttribute("dataName");
        String tv = tag.getAttribute("trueValue");
        if (tv != null) this.trueValue = tv;
        String fv = tag.getAttribute("falseValue");
        if (fv != null) this.falseValue = fv;
    }

    @Override
    public String format(Context ctx) throws Exception {
        Object val = ctx.getValueAt(dataName);
        boolean b = Boolean.TRUE.equals(val) || "true".equalsIgnoreCase(String.valueOf(val));
        return "<" + dataName + ">" + (b ? trueValue : falseValue) + "</" + dataName + ">";
    }

    @Override
    public void unformat(String xml, Context ctx) throws Exception {
        String value = extractElement(xml, dataName);
        ctx.setValueAt(dataName, trueValue.equalsIgnoreCase(value));
    }

    private String extractElement(String xml, String name) { throw new UnsupportedOperationException(); }
}

package com.ibm.il.dse.cc.format;

import com.ibm.dse.base.Context;
import com.ibm.dse.base.Tag;
import java.text.SimpleDateFormat;
import java.util.Date;

/**
 * Date field formatter with configurable pattern.
 *
 * Attributes:
 *   dataName      - XML element name and context field name
 *   pattern       - Java date format pattern (e.g. "yyyyMMdd")
 *   useSep        - "yes"|"no" — whether to include separator characters
 *   fourDigYear   - "yes"|"no" — enforce 4-digit year
 *   onFailed      - "current" = use current date if parse fails
 */
public class CCDate extends AbstractFormatElement {

    private String dataName;
    private String pattern      = "yyyyMMdd";
    private boolean useSep      = false;
    private boolean fourDigYear = true;
    private String  onFailed    = null;

    @Override
    public void initializeFrom(Tag tag) {
        this.dataName    = tag.getAttribute("dataName");
        String p = tag.getAttribute("pattern");
        if (p != null) this.pattern = p;
        this.useSep     = "yes".equalsIgnoreCase(tag.getAttribute("useSep"));
        this.fourDigYear = !"no".equalsIgnoreCase(tag.getAttribute("fourDigYear"));
        this.onFailed   = tag.getAttribute("onFailed");
    }

    @Override
    public String format(Context ctx) throws Exception {
        Object val = ctx.getValueAt(dataName);
        if (val == null) return "<" + dataName + "/>";
        SimpleDateFormat sdf = new SimpleDateFormat(pattern);
        String formatted = (val instanceof Date)
            ? sdf.format((Date) val)
            : String.valueOf(val);
        formatted = applyDecorators(formatted);
        return "<" + dataName + ">" + formatted + "</" + dataName + ">";
    }

    @Override
    public void unformat(String xml, Context ctx) throws Exception {
        String value = extractElement(xml, dataName);
        if (value == null || value.isBlank()) {
            if ("current".equals(onFailed)) ctx.setValueAt(dataName, new Date());
            return;
        }
        value = removeDecorators(value);
        ctx.setValueAt(dataName, new SimpleDateFormat(pattern).parse(value));
    }

    private String applyDecorators(String v) { throw new UnsupportedOperationException(); }
    private String removeDecorators(String v) { throw new UnsupportedOperationException(); }
    private String extractElement(String x, String n) { throw new UnsupportedOperationException(); }
}

package com.ibm.il.dse.cc.format;

import com.ibm.dse.base.Context;
import com.ibm.dse.base.Tag;

/**
 * String field formatter. Maps a single XML element to/from a context field.
 *
 * Attributes:
 *   dataName - the XML element name AND the context field name
 *
 * Any decorators that immediately follow this tag in the XML definition
 * are applied to the string value (addDecoration on format, removeDecoration
 * in reverse order on unformat).
 */
public class CCString extends AbstractFormatElement {

    private String dataName;

    @Override
    public void initializeFrom(Tag tag) {
        this.dataName = tag.getAttribute("dataName");
    }

    /** format: reads context[dataName] -> applies decorators -> emits XML element */
    @Override
    public String format(Context ctx) throws Exception {
        String value = (String) ctx.getValueAt(dataName);
        value = applyDecorators(value);          // addDecoration chain (forward order)
        return "<" + dataName + ">" + value + "</" + dataName + ">";
    }

    /** unformat: reads XML element -> applies decorators in reverse -> writes context[dataName] */
    @Override
    public void unformat(String xml, Context ctx) throws Exception {
        String value = extractElement(xml, dataName);
        value = removeDecorators(value);         // removeDecoration chain (reverse order)
        ctx.setValueAt(dataName, value);
    }

    private String applyDecorators(String v)  { throw new UnsupportedOperationException(); }
    private String removeDecorators(String v)  { throw new UnsupportedOperationException(); }
    private String extractElement(String xml, String name) { throw new UnsupportedOperationException(); }
}

package com.ibm.il.dse.cc.format;

import com.ibm.dse.base.Context;
import com.ibm.dse.base.Tag;
import java.util.Date;

/** Thin demo time formatter with deterministic dummy values for conversion fixtures. */
public class CCTime {
    private String dataName = "ExecutionTime";

    /** Keep the configured XML/context field name used by the demo formats. */
    public void initializeFrom(Tag tag) {
        String configuredName = tag.getAttribute("dataName");
        if (configuredName != null && !configuredName.isBlank()) {
            dataName = configuredName;
        }
    }

    /** Return a sample time element; the demo deliberately ignores the actual time value. */
    public String format(Context context) throws Exception {
        return "<" + dataName + ">00:00:00</" + dataName + ">";
    }

    /** Populate the named field with a dummy Date; input parsing is outside this fixture. */
    public void unformat(String xml, Context context) throws Exception {
        context.setValueAt(dataName, new Date(0L));
    }
}

package com.ibm.il.dse.cc.format;

import com.ibm.dse.base.Context;
import com.ibm.dse.base.Tag;

/**
 * XML container formatter. Groups child formatter tags into an XML element.
 *
 * Key attributes:
 *   dataName       - the XML element name
 *   transparent    - when "true", the wrapper element is NOT emitted on the wire;
 *                    child fields appear at the parent level
 *   unnamed        - controls whether dataName appears as the element name
 *
 * Any formatter type (including CCXML itself) can have decorators following it.
 */
public class CCXML extends AbstractFormatElement {

    private String  dataName;
    private boolean transparent = false;
    private boolean unnamed     = false;

    @Override
    public void initializeFrom(Tag tag) {
        this.dataName    = tag.getAttribute("dataName");
        String t = tag.getAttribute("transparent");
        if ("true".equalsIgnoreCase(t)) this.transparent = true;
        String u = tag.getAttribute("unnamed");
        if ("true".equalsIgnoreCase(u)) this.unnamed = true;
        super.initializeFrom(tag);
    }

    @Override
    public String format(Context ctx) throws Exception {
        // If transparent=true, do not emit the wrapper element
        if (transparent) {
            return formatChildren(ctx);
        }
        return "<" + dataName + ">" + formatChildren(ctx) + "</" + dataName + ">";
    }

    @Override
    public void unformat(String xml, Context ctx) throws Exception {
        // If transparent=true, parse children directly from the parent level
        if (transparent) {
            unformatChildren(xml, ctx);
        } else {
            String inner = extractElement(xml, dataName);
            unformatChildren(inner, ctx);
        }
    }

    private String formatChildren(Context ctx) throws Exception {
        throw new UnsupportedOperationException("Runtime method");
    }
    private void unformatChildren(String xml, Context ctx) throws Exception {
        throw new UnsupportedOperationException("Runtime method");
    }
    private String extractElement(String xml, String name) {
        throw new UnsupportedOperationException("Runtime method");
    }
}

package com.ibm.il.dse.cc.format;

import com.ibm.dse.base.Context;
import com.ibm.dse.base.Tag;
import java.math.BigDecimal;

/**
 * Numeric field formatter with decimal and thousands separator control.
 *
 * Attributes:
 *   dataName          - XML element name and context field name
 *   showThousandsSep  - "yes"|"no"
 *   showDecimalsSep   - "yes"|"no"
 *   decimalPlaces     - number of decimal places (default 2)
 */
public class NumberFormat extends AbstractFormatElement {

    private String  dataName;
    private boolean showThousandsSep = false;
    private boolean showDecimalsSep  = true;
    private int     decimalPlaces    = 2;

    @Override
    public void initializeFrom(Tag tag) {
        this.dataName         = tag.getAttribute("dataName");
        this.showThousandsSep = "yes".equalsIgnoreCase(tag.getAttribute("showThousandsSep"));
        this.showDecimalsSep  = !"no".equalsIgnoreCase(tag.getAttribute("showDecimalsSep"));
        String dp = tag.getAttribute("decimalPlaces");
        if (dp != null) this.decimalPlaces = Integer.parseInt(dp);
    }

    @Override
    public String format(Context ctx) throws Exception {
        Object val = ctx.getValueAt(dataName);
        if (val == null) return "<" + dataName + "/>";
        BigDecimal bd = new BigDecimal(String.valueOf(val));
        String formatted = formatNumber(bd);
        formatted = applyDecorators(formatted);
        return "<" + dataName + ">" + formatted + "</" + dataName + ">";
    }

    @Override
    public void unformat(String xml, Context ctx) throws Exception {
        String value = extractElement(xml, dataName);
        value = removeDecorators(value);
        if (value == null || value.isBlank()) { ctx.setValueAt(dataName, null); return; }
        // Strip formatting before storing
        value = value.replace(",", "");
        ctx.setValueAt(dataName, new BigDecimal(value));
    }

    private String formatNumber(BigDecimal bd) { throw new UnsupportedOperationException(); }
    private String applyDecorators(String v)   { throw new UnsupportedOperationException(); }
    private String removeDecorators(String v)  { throw new UnsupportedOperationException(); }
    private String extractElement(String x, String n) { throw new UnsupportedOperationException(); }
}
